DELIMITER $$
--
-- Procedimentos
--
CREATE PROCEDURE `calcular_saldo_conta` (IN `conta_id` INT, OUT `saldo` DECIMAL(10,2))   BEGIN
    DECLARE saldo_inicial DECIMAL(10,2);
    DECLARE total_movimentacoes DECIMAL(10,2);
    
    -- Obter saldo inicial
    SELECT saldo_inicial INTO saldo_inicial FROM contas WHERE id = conta_id;
    
    -- Somar entradas e subtrair saÃ­das
    SELECT 
        COALESCE(SUM(CASE WHEN tipo = 'entrada' THEN valor ELSE -valor END), 0)
    INTO total_movimentacoes
    FROM movimentacoes_contas
    WHERE conta_id = conta_id;
    
    -- Calcular saldo final
    SET saldo = saldo_inicial + total_movimentacoes;
END$$

DELIMITER ;

